// Generated by build-calendar-runtime.cjs from the shared website schedule and model.
export default "/*\r\n  Weekly schedule and permanent fallback data.\r\n\r\n  Weekly schedule keys follow JavaScript weekdays:\r\n  0 = Sunday, 1 = Monday ... 6 = Saturday.\r\n\r\n  One-day closures and special hours can now be set from the\r\n  NichiNichi Cockpit. The specialDates list below remains as a\r\n  static fallback for longer planned closures if needed.\r\n*/\r\nwindow.NICHI_SITE = {\r\n  calendarSchemaVersion: 1,\r\n  timeZone: \"Europe/Berlin\",\r\n  liveStateEndpoint: \"https://nichinichi-status.fangphaedra.workers.dev/state\",\r\n\r\n  weeklyHours: {\r\n    0: [{ start: \"12:00\", end: \"18:00\", kind: \"cafe\" }],\r\n    1: [\r\n      { start: \"12:00\", end: \"14:00\", kind: \"cafe\" },\r\n      { start: \"18:00\", end: \"20:00\", kind: \"mondstube\" }\r\n    ],\r\n    2: [\r\n      { start: \"12:00\", end: \"14:00\", kind: \"cafe\" },\r\n      { start: \"18:00\", end: \"20:00\", kind: \"mondstube\" }\r\n    ],\r\n    3: [],\r\n    4: [],\r\n    5: [\r\n      { start: \"12:00\", end: \"14:00\", kind: \"cafe\" },\r\n      { start: \"18:00\", end: \"20:00\", kind: \"mondstube\" }\r\n    ],\r\n    6: [{ start: \"12:00\", end: \"18:00\", kind: \"cafe\" }]\r\n  },\r\n\r\n  weeklyActivities: [\r\n    { weekday: 2, de: \"Dienstag · Mother–Daughter Day\", en: \"Tuesday · Mother–Daughter Day\" },\r\n    { weekday: 6, de: \"Samstag · Story Table\", en: \"Saturday · Story Table\" }\r\n  ],\r\n\r\n  specialDates: []\n};\r\n\r\nwindow.NICHI_BILINGUAL_HOURS = [\r\n  { deDay: \"CAFÉ · MO–DI\", enDay: \"CAFÉ · MON–TUE\", deTime: \"12–14 Uhr\", enTime: \"12:00–14:00\" },\r\n  { deDay: \"CAFÉ · MI–DO\", enDay: \"CAFÉ · WED–THU\", deTime: \"geschlossen\", enTime: \"Closed\" },\r\n  { deDay: \"CAFÉ · FR\", enDay: \"CAFÉ · FRI\", deTime: \"12–14 Uhr\", enTime: \"12:00–14:00\" },\r\n  { deDay: \"CAFÉ · SA–SO\", enDay: \"CAFÉ · SAT–SUN\", deTime: \"12–18 Uhr\", enTime: \"12:00–18:00\" },\r\n  { deDay: \"MONDSTUBE · MO–DI & FR\", enDay: \"MONDSTUBE · MON–TUE & FRI\", deTime: \"18–20 Uhr\", enTime: \"18:00–20:00\" }\r\n];\r\n\n/* Shared by public calendar, exports and the existing Cockpit. No network writes. */\r\n(function (root) {\r\n  'use strict';\r\n  const pad = n => String(n).padStart(2, '0');\r\n  function dateKey(date) {\r\n    return `${date.getUTCFullYear()}-${pad(date.getUTCMonth() + 1)}-${pad(date.getUTCDate())}`;\r\n  }\r\n  function berlinToday(now = new Date()) {\r\n    const p = Object.fromEntries(new Intl.DateTimeFormat('en-CA', {\r\n      timeZone: 'Europe/Berlin', year: 'numeric', month: '2-digit', day: '2-digit'\r\n    }).formatToParts(now).filter(p => p.type !== 'literal').map(p => [p.type, p.value]));\r\n    return `${p.year}-${p.month}-${p.day}`;\r\n  }\r\n  function plusDays(key, count) {\r\n    const [y,m,d] = key.split('-').map(Number);\r\n    return dateKey(new Date(Date.UTC(y,m-1,d+count)));\r\n  }\r\n  function periodsFor(key, config, exceptions) {\r\n    const override = exceptions.find(item => item.date === key);\r\n    if (override?.type === 'closed') return [];\r\n    if (override?.type === 'special') return structuredClone(override.periods || []);\r\n    const legacy = (config.specialDates || []).find(item => item.date === key);\r\n    if (legacy?.closed) return [];\r\n    const weekday = new Date(key+'T12:00:00Z').getUTCDay();\r\n    return structuredClone(legacy?.hours || config.weeklyHours?.[weekday] || []);\r\n  }\r\n  function eventText(event, key, language) {\r\n    if (!event) return [];\r\n    const title = event.title?.trim() || '';\r\n    const text = [(event.type === 'dnd' && (!title || title === 'D&D')) ? '' : title, event.description || ''].filter(Boolean);\r\n    if (event.type === 'dnd') {\r\n      text.push(language === 'de' ? 'D&D-Abend: Der Innenraum ist heute belegt.' : 'D&D evening: Indoor seating is occupied tonight.');\r\n      const month = Number(key.slice(5,7));\r\n      if (month >= 10 || month <= 3) text.push(language === 'de'\r\n        ? 'Von Oktober bis März empfehlen wir an D&D-Abenden Take-away.'\r\n        : 'From October to March, we recommend take-away on D&D evenings.');\r\n    }\r\n    return text;\r\n  }\r\n  function month(year, monthIndex, config, exceptions) {\r\n    const first = new Date(Date.UTC(year,monthIndex,1));\r\n    const last = new Date(Date.UTC(year,monthIndex+1,0));\r\n    const offset = (first.getUTCDay()+6)%7;\r\n    const rows = Math.ceil((offset+last.getUTCDate())/7);\r\n    const days = Array.from({length:last.getUTCDate()},(_,i)=>{\r\n      const key=dateKey(new Date(Date.UTC(year,monthIndex,i+1)));\r\n      const periods=periodsFor(key,config,exceptions);\r\n      const exception=exceptions.find(e=>e.date===key);\r\n      return {key,day:i+1,periods,closed:periods.length===0,exception:Boolean(exception),hasEvent:periods.some(p=>p.event)};\r\n    });\r\n    return {year:first.getUTCFullYear(),monthIndex:first.getUTCMonth(),offset,rows,days};\r\n  }\r\n  function periodLabel(p) { return `${p.kind === 'mondstube' ? 'Mondstube' : 'Café'} ${p.start}–${p.end}`; }\r\n  // One weekly layout/summary for both the page and unchanged IG/A4 artwork.\r\n  function operatingLayout(config, language) {\r\n    const de=language==='de', locale=de?'de-DE':'en-GB';\r\n    const orderedDays=[1,2,3,4,5,6,0];\r\n    const weekdays=orderedDays.map((_,i)=>new Intl.DateTimeFormat(locale,{weekday:'short',timeZone:'UTC'}).format(new Date(Date.UTC(2026,0,5+i))).replace(/\\.$/,''));\r\n    const columns=orderedDays.filter(day=>(config.weeklyHours?.[day] || []).length>0);\r\n    const breaks=columns.map((d,i)=>i>0 && orderedDays.indexOf(d)-orderedDays.indexOf(columns[i-1])>1);\r\n    function dayNames(days) {\r\n      const indexes=days.map(day=>orderedDays.indexOf(day)).sort((a,b)=>a-b),groups=[];\r\n      for(let i=0;i<indexes.length;i++){\r\n        let end=i;while(end+1<indexes.length && indexes[end+1]===indexes[end]+1)end++;\r\n        groups.push(weekdays[indexes[i]]+(end>i?'–'+weekdays[indexes[end]]:''));i=end;\r\n      }\r\n      return groups.join(', ');\r\n    }\r\n    const summary=[];\r\n    for(const kind of ['cafe','mondstube']){\r\n      const groups=new Map();\r\n      for(const day of orderedDays)for(const period of config.weeklyHours?.[day] || []){\r\n        if(period.kind!==kind)continue;\r\n        const time=period.start.replace(/:00$/,'')+'–'+period.end.replace(/:00$/,'');\r\n        if(!groups.has(time))groups.set(time,[]);groups.get(time).push(day);\r\n      }\r\n      if(groups.size)summary.push((kind==='cafe'?'Café':'Mondstube')+' · '+[...groups].map(([time,days])=>dayNames(days)+' '+time).join(' · '));\r\n    }\r\n    const closed=orderedDays.filter(day=>!(config.weeklyHours?.[day] || []).length);\r\n    if(closed.length)summary.push(dayNames(closed)+' · '+(de?'Ruhetage':'Closed'));\r\n    return {orderedDays,weekdays,columns,breaks,summary};\r\n  }\r\n  root.NICHI_CALENDAR = {apiVersion:1,berlinToday,plusDays,periodsFor,eventText,month,periodLabel,operatingLayout};\r\n})(typeof window === 'undefined' ? globalThis : window);\r\n";
